estilos_originais_referencia:
*{box-sizing:border-box}
body{font-family:Arial,Helvetica,sans-serif;color:#17324d;background:#fff;margin:0}
.mfc-act{max-width:980px;margin:0 auto;padding:24px 18px 48px}
.mfc-act h1{font-size:30px;text-align:center;margin:0 0 8px;color:#173f63}
.mfc-sub{text-align:center;font-size:17px;margin:0 auto 20px;max-width:760px;line-height:1.5}
.mfc-meta{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin:18px 0}
.mfc-chip{background:#eef5fa;border:1px solid #c8dce9;border-radius:999px;padding:8px 14px;font-weight:700}
.mfc-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:20px 0 28px}
.mfc-btn{display:inline-block;background:#173f63;color:#fff!important;text-decoration:none;border:0;border-radius:8px;padding:11px 18px;font-weight:700;cursor:pointer}
.mfc-btn:hover{background:#2f75a8}
.mfc-note{background:#fff8dd;border-left:5px solid #f2c94c;padding:12px 14px;border-radius:6px;margin:16px 0 24px;line-height:1.5}
.q{border:1px solid #d8e2ea;border-radius:12px;padding:18px;margin:18px 0;break-inside:avoid}
.q h2{font-size:19px;margin:0 0 10px;color:#173f63}
.q p{font-size:17px;line-height:1.55;margin:8px 0}
.art{margin:14px auto 16px;padding:14px;border-radius:10px;background:#f7fafc;border:1px solid #dfe8ef;max-width:760px}
.art-title{text-align:center;font-weight:700;margin-bottom:10px;color:#173f63}
.tbl{width:100%;border-collapse:collapse;font-size:16px}
.tbl th,.tbl td{border:1px solid #b9cad7;padding:9px;text-align:center}
.tbl th{background:#173f63;color:#fff}
.digital{font-family:"Courier New",monospace;font-size:42px;letter-spacing:5px;text-align:center;background:#17212b;color:#d7ffb8;padding:18px;border-radius:8px}
.digital .hi{color:#ffd54f;font-weight:700}
.place{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;text-align:center}
.place div{border:1px solid #9fb4c3;border-radius:6px;padding:9px}
.place .hd{background:#173f63;color:#fff;font-weight:700}
.route{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px}
.node{background:#fff;border:2px solid #2f75a8;border-radius:8px;padding:10px 12px;font-weight:700}
.arrow{font-size:24px;font-weight:700}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px}
.card{background:#fff;border:2px solid #c7d8e5;border-radius:9px;padding:13px;text-align:center}
.card strong{display:block;font-size:22px;color:#173f63;margin-top:5px}
.decomp{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.decomp span{background:#e9f3f9;border:1px solid #9fc1d7;border-radius:7px;padding:10px 12px;font-weight:700}
.numberline{position:relative;margin:32px 20px 18px;height:60px;border-top:4px solid #173f63}
.tick{position:absolute;top:-12px;width:2px;height:20px;background:#173f63}
.tick label{position:absolute;top:24px;transform:translateX(-50%);white-space:nowrap;font-weight:700}
.material{display:flex;justify-content:center;gap:14px;align-items:stretch;flex-wrap:wrap}
.material .box,.material .pack,.material .unit{
    border-radius:8px;
    text-align:center;
    font-weight:700;
    display:flex;
    align-items:center;
    justify-content:center;
    flex-direction:column;
    line-height:1.25;
    padding:10px 8px;
    min-height:72px;
}
.material .box{width:125px;background:#d8edf8;border:2px solid #2f75a8}
.material .pack{width:110px;background:#fff0c7;border:2px solid #e8b64c}
.material .unit{width:72px;background:#f1e2ff;border:2px solid #9666c3}
.score{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}
.score div{background:#173f63;color:white;padding:12px;border-radius:8px;text-align:center}
.score b{display:block;font-size:23px;margin-top:4px}
.seq{display:flex;justify-content:center;gap:8px;flex-wrap:wrap}
.ticket{border:2px dashed #2f75a8;border-radius:8px;padding:10px 14px;background:white;font-weight:700;font-size:20px}
.labels{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;max-width:520px;margin:auto}
.label{padding:14px;border-radius:8px;background:#fff;border:2px solid #173f63;text-align:center;font-size:22px;font-weight:700}
.answer-lines{height:54px;border-bottom:1px dashed #b9c7d2}
.footer-note{text-align:center;color:#63788a;font-size:13px;margin-top:28px}
@media(max-width:600px){
 .mfc-act{padding:18px 12px 36px}
 .mfc-act h1{font-size:24px}
 .q p{font-size:16px}
 .digital{font-size:32px}
 .score{grid-template-columns:repeat(2,1fr)}
 .labels{grid-template-columns:1fr 1fr}
}
@media print{
 .mfc-actions{display:none!important}
 body{background:#fff}
 .mfc-act{max-width:none;padding:0}
 .q{break-inside:avoid}
 a{color:#000!important;text-decoration:none!important}
}

.mfc-brand{text-align:center;margin:2px 0 8px;font-family:Georgia,"Times New Roman",serif;font-style:italic;font-weight:700;font-size:34px;line-height:1}
.mfc-brand-name{color:#173f63}.mfc-brand-fc{color:#d6a400;margin-left:2px}

.mfc-gabarito{margin:34px 0 10px}
.mfc-gabarito details{border:1px solid #c8dce9;border-radius:10px;overflow:hidden;background:#fff}
.mfc-gabarito summary{cursor:pointer;background:#173f63;color:#fff;font-size:18px;font-weight:700;padding:13px 18px;list-style:none}
.mfc-gabarito summary::-webkit-details-marker{display:none}

.mfc-gabarito-conteudo{padding:14px 18px;background:#f7fafc}
.mfc-gabarito-conteudo p{font-size:16px;line-height:1.5;margin:8px 0;padding-bottom:8px;border-bottom:1px solid #e2e9ee}

.mfc-gabarito summary{
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:12px;
}
.mfc-gabarito-seta{
    display:inline-block;
    width:10px;
    height:10px;
    border-right:3px solid #ffffff;
    border-bottom:3px solid #ffffff;
    transform:rotate(45deg);
    transition:transform .2s ease;
    flex:0 0 auto;
    margin-right:2px;
}
.mfc-gabarito details[open] .mfc-gabarito-seta{
    transform:rotate(225deg);
}

@media print{.mfc-gabarito{display:none!important}}
